import{_ as t}from"./chunks/9ea65ceb2803698a6dee.CZDsoUrT.js";import{_ as l,C as r,o as i,c as o,j as e,a as h,E as m,a5 as n}from"./chunks/framework.DNkHA0lr.js";const A=JSON.parse('{"title":"80小时神话（为什么我们对「忙碌」上瘾）","description":"","frontmatter":{"title":"80小时神话（为什么我们对「忙碌」上瘾）","originalTitle":"The 80-Hour Myth (Why We’re Addicted To Being Busy)","date":"2025-04-26","originalUrl":"https://thedankoe.com/letters/the-80-hour-myth-why-were-addicted-to-being-busy/","minutes":21,"sourceHash":"f4deed2f8b93ead6309d9f289e218c31f79b5ef514dc1ff8d1f47c582bc98632","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-80-hour-myth-why-were-addicted-to-being-busy/"}]]},"headers":[],"relativePath":"letters/the-80-hour-myth-why-were-addicted-to-being-busy.md","filePath":"letters/the-80-hour-myth-why-were-addicted-to-being-busy.md"}'),s={name:"letters/the-80-hour-myth-why-were-addicted-to-being-busy.md"};function d(u,p,c,b,f,_){const a=r("ArticleMeta");return i(),o("div",null,[p[0]||(p[0]=e("h1",{id:"_80小时神话-为什么我们对「忙碌」上瘾",tabindex:"-1"},[h("80小时神话（为什么我们对「忙碌」上瘾） "),e("a",{class:"header-anchor",href:"#_80小时神话-为什么我们对「忙碌」上瘾","aria-label":'Permalink to "80小时神话（为什么我们对「忙碌」上瘾）"'},"​")],-1)),m(a),p[1]||(p[1]=n('<p><a href="https://www.youtube.com/embed/65N6sQfQDV8?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>自我有记忆以来，我就不想把自己的一生耗费在工作上。</p><p>反面榜样在我周围随处可见。</p><p>而我小时候观察力还挺强。</p><p>我不想凌晨4点起床，5点出门上班，埋头苦干，晚上7点才回家——只因为我在努力养家、打两份工——结果回到家还要面对一个随时准备吵架、或者告诉我家里还有多少事没做的配偶。</p><p>我就让你自己去填补细节吧，因为光是这一句话，就已经让我因为童年中那些（夹杂在<em>许多</em>美好之间的）负面回忆而情绪波动了。</p><p>这就是为什么我拒绝走那条路。</p><ul><li>在我十几岁的时候，我一直在琢磨怎样才能用最少的工作量赚最多的钱。</li><li>在大学里，我一边上课一边打零工。我每天会花2-3个小时做副业项目，或者通过Udemy课程和YouTube学习。</li><li>当我第一次有全职工作时，我会在1个小时的通勤路上学习（有声书、播客、YouTube），并把工作任务拖延一两个小时，用来搭建我当时的副业。</li></ul><p>我想说的重点是这个：</p><p>我并没有每天12到16个小时去「拼命硬干」搞副业。</p><p>如果我不对自己撒谎、能真正合理安排时间，我每天只有1到4个小时。</p><p><img src="'+t+'" alt=""></p><p>这是一件真的让我生气的事。除此之外我算是相当淡定的人了（至少我自己觉得是）。</p><p>几天前，X上有个人说：</p><p>「你处在这个位置说这话当然轻松，但对新手来说不是这样的」——这是针对我说过的一句话做出的评论，我说你需要休息才能做出最好的成果。</p><p>人们一直这么说，即便是在我教写作的时候，好像我教的不是<em>我作为新手时真正做过的事</em>。如果你的方法真的更好，那把你的成果拿出来给我看看。</p><p>我为什么会为此莫名生气：因为年轻人已经被灌输成把「盲目苦干」当作一种身份象征，而这种身份象征伪装成了通往成功的有效策略。</p><p>我在这里要拆解的，正是这种导致95%的新手和企业整体失败的愚蠢思维方式。「苦干」不是智慧，也不是策略，恰恰是缺乏智慧和策略的表现。</p><p>我当年靠一次1到4个小时的工作时间，搞出了让我辞职的副业。</p><p>当我开始全职做自己的事业时，工作时间也差不多。</p><p>如今我已经写了2本书，做了将近10个产品，运营着一家软件初创公司，也积累了相当庞大的关注者群体，我相当确信一个事实：大多数人不是在浪费时间，就是根本不知道自己不知道什么。</p><p>如果你每天苦干12小时以上，尤其是作为新手，我可以保证，<em>一定有办法</em>在每天工作不到4小时的情况下取得更多成果。</p><p>事实上，我甚至可以说，如果你每天工作超过4小时，那你至少在做一些错误的事情，一定<em>有</em>可以改进的空间。</p><p>你可以放弃那些不起作用的事情。</p><p>你可以用AI加速琐碎工作 <a href="https://stan.store/thedankoe/p/mini-course-how-i-systemize-my-life-with-ai" target="_blank" rel="noreferrer">（其实我刚做了一个免费的迷你课程，讲我如何用AI，因为很多人问我这个）</a>。</p><p>你可以发现自己的优势，专注于杠杆点。</p><p>但你可能就是不想意识到这一点，因为这样你就无法融入这个崇拜忙碌的世界。人的心智是个很微妙的东西。</p><p>如果你理解了闲暇与杠杆的重要性（这个说法可以当一本书的标题，哦天哪，我下一本书就写这个……点子生点子），你的生产力、思维和生活方式都会发生转变。</p><h3 id="长时间工作何时才有意义" tabindex="-1">长时间工作何时才有意义 <a class="header-anchor" href="#长时间工作何时才有意义" aria-label="Permalink to &quot;长时间工作何时才有意义&quot;">​</a></h3><p>我在这里不是要说服你，每天工作不到4小时才是唯一正确的方式。</p><p>这只是一种方式。</p><p>你也不会一辈子只走一条路。</p><p>生产力是按季节变化的。</p><p>某个阶段，你可能只工作4个小时。</p><p>另一个阶段，你可能工作16个小时。</p><p>有时是6、2、8、10，或者其他任何数字，因为投入和产出之间往往不是线性关系。</p><p>我自己也有不少时候忍不住长时间工作，而且我很享受那种状态。</p><p>但系统（尤其是生产力系统）不会永远停留在单一状态。它们会演变，会适应当下的情境，也会迅速崩溃，让你失去方向（就像你几年前痴迷的那个Notion生产力系统，当时用着挺开心，也确实帮到了你，但放到你现在这个阶段，就纯属浪费时间）。</p><p>我写这篇文章的目的，是要证明持续16小时的「苦干模式」不会把你带得像你想象中那么远。</p><p>持续每天工作12到16小时不是一种性格特质，而是一种严重失调的信号，是对你大脑运作方式的普遍忽视。</p><p>我只希望你读完这篇文章之后再形成固定的看法，因为即便是这个「看法」本身，也是一个会在你最需要它时崩溃的系统。</p><h2 id="_80小时神话——为什么我们对忙碌上瘾" tabindex="-1">80小时神话——为什么我们对忙碌上瘾 <a class="header-anchor" href="#_80小时神话——为什么我们对忙碌上瘾" aria-label="Permalink to &quot;80小时神话——为什么我们对忙碌上瘾&quot;">​</a></h2><blockquote><p>创作者的悖论：</p><p>创造力，是不试图变得有创造力的结果。</p></blockquote><p>人类是模仿性的生物。</p><p>我们通过模仿来生存，避免被驱逐（无论是被家族……还是被这个痴迷生产力的文化所抛弃）。</p><p>我们的心智会塑造成能让我们融入群体的样子。</p><p>问题的根源在于，每个人都在美化那种<em>看得见的极端。</em></p><p>我们会觉得那个「靠苦干」在3周内做出百万美元生意的年轻创业奇才特别励志。</p><p>这种感觉很有代入感。谁都能做到，对吧？既然我一生都被教导要工作更长时间、更努力，那么工作得越久越拼，我就越有可能得到我想要的东西，对吧？一切都只关乎努力工作，对不对???</p><p>错了。</p><p>你和我都清楚，背后有一个更深层的公式在起作用。</p><p>我们都清楚，那种由无意识的熟练技巧激发出的精彩瞬间集锦，并不是现实。</p><p>我们都清楚，你可以花上一万个小时写十本书，结果读者却不超过50人，而这会让一些人恼火，因为有人明白如何分发一本质量平平的书，就能卖出数百万本，把你远远甩在身后——因为他们专注于能带来结果的事情。</p><p>大多数人都错过了这背后的语境。</p><p>他们错过了真正促成大多数创作者、远见者和策略家取得成功的那种<em>看不见的极端</em>。</p><p>就拿查尔斯·达尔文（Charles Darwin）来说。</p><p>你知道的，那个一生写了19本书、发现了进化论、并改变了我们所知世界的人——他每天只工作4到5个小时，之后是大量的长时间散步、阅读和其他闲暇活动，正是这些活动为他的思维注入了各种想法，让他能完成如此宏大的任务。</p><p>你和他的区别在于，那是他毕生的事业。</p><p>花多长时间都无关紧要。</p><p>而对你来说，却是不成功便成仁。你要么在6个月内成功，要么就放弃、永远接受命运——这想法既荒谬又本末倒置。而那种持续的压力和求生状态，肯定也无助于你实现目标。</p><p>当我们真正去审视（1）成功人士的生活方式，以及（2）人类大脑与心理学事实，就能发现一些真相。</p><p>首先，我们所仰慕的大多数创作者，其日常作息都惊人地相似。</p><p>他们都有高强度的专注工作时段，之后紧接着是彻底放松、完全脱离工作的休息时间。</p><p>就拿大卫·奥格威（David Ogilvy）来说，这位传奇广告人和文案撰稿人，坚信要先做大量深入的研究，把一切可能的信息都写下来，然后放手离开，让潜意识去处理这个问题。</p><blockquote><p>伟大的想法来自潜意识。这在艺术、科学和广告业都是如此。但你的潜意识必须先被充分地填充信息，否则你的想法就会毫不相关。先把意识层面填满信息，然后解开你理性思维的束缚。</p><p>——奥格威</p></blockquote><p>那些伟人的长时间散步、阅读和闲暇时光，正是激活大脑「默认模式网络」（Default Mode Network，简称DMN）的关键。也就是说，当你停止专注于工作时，你的潜意识会继续替你工作，往往以一种更具创造性、更高效的方式，把想法呈现给你的意识（参见：淋浴时的灵感），为你的工作带来新意和创新。</p><blockquote><p>其他科学家发现，默认模式网络（DMN）的复杂程度决定了我们自我意识、记忆力、想象未来的能力、共情能力和道德判断力的强弱[……]其他科学家还发现，你的DMN越发达，你就越能构建出理解他人心智的模型。</p><p>——《休息》，亚历克斯·庞（Alex Pang）</p></blockquote><p>换句话说，<em>你所做的最有效、最能产出成果的「工作」，恰恰发生在你完全不工作的时候</em>。对于那些身份认同深深绑定在「苦干」上的人来说，这是一个极难接受的事实——他们的大脑甚至还没来得及思考，就已经条件反射般地反驳这句话。</p><p>如果这说的就是你，那你应该去散散步，因为正是这种毫无效果的思维方式，让你一事无成。</p><p>当你深度专注于一连串任务时，你的心智会被窄化，锁定在那种类似电子游戏任务的框架里。你根本无法、也不能跳出这个任务去看问题。你只是坐下来，完成你已经学会或已经规划好该怎么做的事情。你几乎只能局限于大脑中已经存在的那些想法。你的心智并不在尝试想出<em>新</em>的点子，即便有，也是寥寥无几、断断续续。</p><p>大多数伟大的想法，都来自于经过充分信息积累的自我反思。</p><h2 id="拖延的力量——这不是懒惰-而是我们的天性所在" tabindex="-1">拖延的力量——这不是懒惰，而是我们的天性所在 <a class="header-anchor" href="#拖延的力量——这不是懒惰-而是我们的天性所在" aria-label="Permalink to &quot;拖延的力量——这不是懒惰，而是我们的天性所在&quot;">​</a></h2><blockquote><p>你我都不是牛。我们不是天生要整天吃草的动物。我们生来就该像狮子一样去狩猎。在我们的杂食性演化中，我们更接近肉食动物，而不是草食动物。作为一名智力上的运动员，你应该像运动员那样运作。也就是说，你先高强度训练，然后全力冲刺，然后休息，然后重新评估。以为你能靠每天用同样的时间坐在那儿死磕，就能获得线性产出——那是机器的逻辑。机器才该朝九晚五地工作，人类不是。</p><p>——纳瓦尔（Naval）</p></blockquote><p>大多数人内心深处都有一些恐惧和渴望，把他们绑在了「苦干」上：</p><ul><li>他们把那条漫长而艰难的路浪漫化了</li><li>他们内心深处有创伤，让他们想向那些根本不在乎的人证明自己</li><li>他们在一个节俭的家庭中长大，因此延迟自己的成功，因为内心深处，他们害怕赚钱</li><li>他们觉得自己还不配拥有杠杆，所以什么事都自己干，或者试图一次性把所有事都做完</li></ul><p>现实是……</p><p>现在已经不再被允许说「我发现并利用了一条捷径」了。</p><p>当你停止那么拼命地工作，转而面对无聊时，会有种落后于人的感觉。</p><p>但对古希腊人来说——我们一直把他们当作智慧的支柱来引用——闲暇才是文明生活的巅峰。</p><p>工作是必要的，但次于闲暇。</p><p>最近我自己也重新发现了这一点。</p><p>作为一个自命不凡的「初创公司创始人」，我曾觉得自己需要整天苦干，才能跟上当下正在发生的AI竞赛。</p><p>两个月后，我的写作开始变差。感觉自己无法清晰地思考了。</p><p>我会回顾自己以前写的东西，然后想：「我到底是怎么写出那样的东西的？」</p><p>不是因为它是我见过最好的东西，差得远呢，而是因为我能用如此引人入胜的方式表达我的想法。我的愿景很清晰。那时，尽管未来极不确定，我的生活却感觉很稳定。</p><p>我回想起自己那些长时间的散步，那时我的大脑会因不同世界观和哲学之间的联系而点亮。</p><p>我很怀念那种感觉。</p><p>仿佛有什么东西给我的模式识别能力上了一个限制器。</p><p>如果我能设法把那种感觉找回来……它其实会<em>帮助</em>我的事业，而不是伤害它。</p><p>所以，我开始<em>有意识地</em>在一天中安排更多休息。</p><p>也就是即使我有冲动，也强迫自己<em>不</em>去工作。</p><p>一开始感觉很不对劲。感觉自己在掉队。但我的大脑在慢慢地、然后突然一下子地感谢我。</p><p>我的创造力正带着一股复仇般的力量回归。我能像以前一样清晰地思考。而从这篇文章你大概也能看出来，把多个领域的想法编织在一起对我来说已经不再是问题了。</p><p>我最近YouTube视频那种千篇一律的乏味，并不是产出不足的结果，而是休息不足的结果。</p><h3 id="像狮子一样工作-而不是像牛一样" tabindex="-1">像狮子一样工作，而不是像牛一样 <a class="header-anchor" href="#像狮子一样工作-而不是像牛一样" aria-label="Permalink to &quot;像狮子一样工作，而不是像牛一样&quot;">​</a></h3><p>工作有两种方式。</p><p>第一种，像在田野里吃草的牛：</p><ul><li>每天持续长时间工作</li><li>稳定且可预测的产出</li><li>以线性方式用时间换金钱</li><li>无论精力如何都规律地出现</li><li>常常导致精力耗尽和收益递减</li></ul><p>第二种，像狮子——在这方面，我们和狮子拥有相似的心理构造，因为我们都是<em>猎手</em>（至少在工作这件事上是这样）。</p><p>我们的大脑渴望新奇感和多巴胺，这种感觉伴随着发现有助于我们生存的资源（比如想法）而来：</p><ul><li>专注、高能量的密集工作爆发</li><li>在“捕猎”之间安排长时间的休息和恢复</li><li>根据精力和创造力周期来工作</li><li>把影响力置于工作时长之上</li><li>追求杠杆，让结果不再与<em>时间</em>绑定</li></ul><p>按今天的观念来看，狮子简直是个超级拖延症患者，而人们对此不以为然。他们会让你为花时间而感到内疚。他们会告诉你，你缺乏自律，应该更认真对待事情。</p><p>如果你不擅长及时回复别人的短信，或者你总是把工作（或作业）拖到最后一刻，这不是性格缺陷，而是很多人本来就是这样的构造。</p><p>如果这听起来像你，那你需要明白的是：强度胜过持续时间，休息才是最具生产力的工作形式，而结果比工时更重要。</p><p>但这里面有几个变动的因素。</p><p>第一，是利用你独特的优势，从而获得不对称的优势。</p><p>第二，是选择那种能让你把生活方式放在首位的工作。</p><p>这样，你就可以按照自己的精力周期来工作，<em>并</em>有意识地选择自己应该专注做什么。有些创作者喜欢工作到深夜，而另一些人更偏爱早晨。</p><p>如果有人告诉你该做什么，那你无法真正改变这一点，而你的首要任务必须是离开那份工作。</p><h2 id="如何少工作、多赚钱、享受生活" tabindex="-1">如何少工作、多赚钱、享受生活 <a class="header-anchor" href="#如何少工作、多赚钱、享受生活" aria-label="Permalink to &quot;如何少工作、多赚钱、享受生活&quot;">​</a></h2><p>要像狮子一样工作，你需要清晰。</p><p>让我们把这条原则称为“科氏剃刀”（Koe&#39;s Razor）：</p><p><em>如果你需要强迫自己去工作，那说明你在做错的事情。</em></p><p>如果你对某个能让你离愿景更近一步的想法、项目或策略拥有绝对的清晰度，你就不需要自律。你会情不自禁地去工作。你会进入心流状态，以极高的质量迅速完成它。</p><p>我大多数最好、最出色的项目就是这样完成的。</p><p>我会尽情享受悠闲，常常到了觉得自己应该在工作的程度，直到项目截止日期临近，而我对如何完成它已经有了足够的清晰度。</p><p>然后，它成了我脑子里唯一想的事情。我的注意力变得狭窄，干扰归零。而一旦项目完成，我就回到一种“维护模式”，只做维持某种进展所需的最少工作量，因为我从经验中知道，如果我硬逼着自己再多做，结果只会让我失望。</p><p>那么，为了少工作，需要满足几个条件：</p><ol><li>你必须定义并遵循你理想的生活方式。</li><li>你独特的优势必须与一种以杠杆为基础的游戏相契合。</li><li>你需要具备对工具和技术的认知，作为一个人也能利用它们在更短时间内做更多事情。</li></ol><p>说完这些，让我们开始吧：</p><h3 id="_1-理想的生活方式决定专注方向" tabindex="-1">1）理想的生活方式决定专注方向 <a class="header-anchor" href="#_1-理想的生活方式决定专注方向" aria-label="Permalink to &quot;1）理想的生活方式决定专注方向&quot;">​</a></h3><p>创造你理想生活的最好方式，就是现在就去过它——只是规模更小一些。</p><p>如果你想成为一名作家，而你还没有开始写作，你永远不会成为作家。</p><p>但如果你现在就开始写作，即使你每天只有30分钟，你也可以慢慢地增加投入写作的时间。</p><p>因为如果你不去写作——或者不去设计、创作、编程等等——你就没有参与到纠错的过程中。你没有遇到那些能让你变得更好的真实世界反馈。在你真正开始之前，无论是现在开始，还是等你变得更“有知识”时才开始，你都在延迟你能够全职去做那件事所需的准备时间。</p><p>要少工作，<em>你做出的每一个决定都必须经过你理想生活方式这个筛选器。</em></p><p>这幅“理想生活方式”的画面并不是一个静态的目标，它是一件不断演变的艺术品。我无法告诉你它是什么，因为这取决于你自己对过去那些你不想再经历一次的经历的反思，以及朝着你认为自己想要的未来经历不断试错，直到它们变成你能用清醒的眼光看清楚的过去经历。</p><p>现在，你能做的最有用的事情之一，就是设定<em>反目标（anti-goals）</em>。</p><p>换句话说：</p><p>为了取得成功，你<em>不</em>愿意牺牲什么？</p><p>你愿意牺牲你的健康吗？</p><p>不愿意？</p><p>那么每天16小时的工作时长自然就被排除了。</p><p>那和你另一半相处的时间呢？你的智力发展？社交生活？</p><p>很多人会把这看作是限制，其实它极其自由，因为创造力恰恰在约束中蓬勃发展。</p><p>在不牺牲健康这一约束下，你必须（1）选择一种有利于这一点的职业或商业模式，（2）对更多的承诺说“不”，从而释放更多的专注力，以及（3）把工作的质量置于数量之上。</p><p>当你不能无限延长工作时间时，你就被迫充分利用你已有的时间，从而带来更专注、往往也更出色的结果。</p><h3 id="_2-无需许可的杠杆" tabindex="-1">2）无需许可的杠杆 <a class="header-anchor" href="#_2-无需许可的杠杆" aria-label="Permalink to &quot;2）无需许可的杠杆&quot;">​</a></h3><p>到目前为止，我们忽略了一个关键点，那就是机械性工作和创造性工作之间的区别。</p><p>机械性工作可以相对轻松地每天做16个小时，因为它并不需要太多的脑力。</p><p>但杠杆并不是从那里来的。</p><p>而且，你仍然在忽视你生活的其他部分。</p><p>所以，如果你脑子里仍在跟我争辩，说你可以整天工作并完成大量高质量的工作，那这很可能是机械性工作，而你可能还是更适合少工作一些，这样你就不会在长达40年的时间里，一直拖延着你在生活其他领域本该完成的所有工作。</p><p>这不是说大量工作总是坏事，但在三种杠杆中，它是最低级的一种：</p><ol><li><strong>劳动杠杆</strong>——增加你花在任务上的时间，或者把工作外包给别人。（缺点：管理开销和复杂性）</li><li><strong>资本杠杆</strong>——你的钱通过投资为你工作。（缺点：需要已有的财富或值得投资的东西）</li><li><strong>无需许可的杠杆</strong>——现代最强大的杠杆形式。（缺点：大多数人看起来都在做同样的事情）</li></ol><p>每一种都有各自的优点，但我们生活在历史上最“无需许可”的时代。</p><p>无需许可的杠杆以代码、媒体、书籍、播客、推文、通讯、课程等形式存在。</p><p>这些东西的边际复制成本为零。</p><p>换句话说，一次构建，卖多少次都行。</p><p>一旦一件软件、内容或数字资产被创造出来，你就可以以几乎零成本分发额外的副本。一个数字产品可以服务一百万用户。</p><p>为什么这一点很重要？</p><p>因为从未有过这样一个时代——如此多的权力掌握在个人手中。</p><ul><li>一个人（或一个小团队）借助互联网，无需守门人就能达到全球规模</li><li>数字产品不需要<em>许可</em>才能构建或分发</li><li>它们对时间投入的回报往往是指数级的，而不是线性的</li></ul><p>这就是人们感到困惑的地方：</p><p>第一，他们认为自己（又）必须苦干式地大量产出内容才能建立起任何形式的受众。但如果你批判性地思考，你就知道这不是真的。你知道，凭借<em>质量和持续的产出</em>，你更有机会让作品传播给更多喜爱它的人。</p><p>我每天写3条推文（偶尔加一个帖子串），坚持了2年，粉丝增长到超过10万。</p><p>区区3条推文，根本谈不上什么“苦干”。其他的增长策略也是如此。我每周在这上面花的时间<em>大概</em>只有5到10个小时。</p><p>一个数字产品需要花些时间（好吧，其实现在也不用太久了，因为<a href="https://youtu.be/QsyhyMpvPR4" target="_blank" rel="noreferrer">如果你对想要构建的东西有清晰的想法，AI可以加快这个过程</a>），大概每天1-2小时，持续一个月，具体取决于产品类型。</p><p>而一个落地页只需要几个小时就能搭建好（同样，<a href="https://youtu.be/z9dtU-xUX04" target="_blank" rel="noreferrer">你现在可以用AI来做这件事</a>），但一旦搭建完成，你就完全可以只专注于用内容来引流。</p><p>如果我想保持一人企业的状态，并获得合理的收入，我看不出为什么我<em>不能</em>仅凭内容和一个已经搭建好的数字产品，每周工作5到10个小时。</p><p>当然，我天生不是那种性格（总有一刻我会感到<em>捕猎</em>的冲动），所以随着我积累了足够的资源，我用其他项目和事业填满了自己的时间。</p><p>最后，这条路并不是为任何特定人群保留的。</p><p>你的任何兴趣或技能，都可以转化为数字产品和内容，与那些有相似兴趣或技能的人产生共鸣。</p><p>如果你想少工作，这是初学者建立起最初杠杆的最佳起点之一。</p><p>一旦你拥有了足够的现金、资本、技能，以及以受众形式存在的分发渠道，接下来要构建什么就完全取决于你自己了。</p><h3 id="_3-对ai的新看法" tabindex="-1">3）对AI的新看法 <a class="header-anchor" href="#_3-对ai的新看法" aria-label="Permalink to &quot;3）对AI的新看法&quot;">​</a></h3><p>我使用AI越多，就越意识到自己不是在外包我的思考，而是在<em>增强它</em>。</p><p>当我尝试让AI以更准确的方式执行一项任务（而不是用一句“帮我写一整本书”的提示词对它大喊大叫）时，我会接触到清晰而智慧的思考。我读得更多了。我理解得更多了。我更多地暴露出自己的盲点，因为我的指令很多时候第一次并不清晰。</p><p>我觉得这件事威力巨大，所以我没有为此专门写多篇通讯，而是<a href="https://stan.store/thedankoe/p/mini-course-how-i-systemize-my-life-with-ai" target="_blank" rel="noreferrer">把我所有的AI使用案例都放进了这个免费的迷你课程</a>（唯一的说明是，我用自己的软件来教授它）。</p><p>当我写通讯或读书时,我经常借助AI来帮助学习。我会请AI澄清一些我原本已经掌握得不错的概念，比如“无需许可的杠杆”，但AI帮助我加深了这种理解。这就像在读一本实时为你量身定制的书。</p><p><em>AI正在缩小学习与实践之间的差距。</em></p><p>由于AI可以根据你的指令完成任务，比如撰写落地页文案或制定病毒式营销计划，你在<em>完成</em>任务的同时，也在<em>学习</em>如何在下次更好地完成它。</p><p>一个你不断打磨和重复使用的“提示词”，反映了你对该任务的理解。它是一个外部化的创意流程克隆，不再需要停留在你的脑子里，或者停留在一份静态的SOP文档中。</p><p>以下是我现在喜欢使用AI的方式：</p><ul><li>我选择一项要完成的任务，比如制作一个更好的YouTube开场</li><li>我找一个YouTube视频、PDF或参考文本，让AI把它拆解成可复制的步骤</li><li>我把它变成一个可以反复重复使用的元提示词</li><li>我在使用过程中不断打磨这个提示词</li></ul><p>再举个例子，前几天我看到一个品牌在Twitter上做产品发布，获得了1100万次浏览。我想要那样的结果，所以我按照上面的步骤，把他们所有的营销素材粘贴进了AI。</p><p>现在，我为我们下一个重大的<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>发布制定了一套“范式转变营销”策略。</p><p>另一件你可以做的事——如果你读过米哈里·契克森米哈伊（Mihaly Csikszentmihalyi）的《心流》（Flow）这本书——就是下载这本书的PDF，把它喂给AI，然后创造出很多东西，比如：</p><ul><li>一套晨间练习，帮你进入你计划要做的任务所需的心流状态</li><li>一个清晰度顾问，帮你选择能给生活带来更多意义的技能和职业</li><li>一个私人治疗师，把无聊转化为兴趣，把焦虑转化为行动</li></ul><p>书籍、视频、课程和其他信息来源不再是<em>静态</em>的了。这些信息现在可以为你<em>做事</em>了。如果你把我的<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2小时写作者</a>课程以聪明的方式喂给它，它写出来的帖子、推文串和通讯，会比你自己能写出来的好得多。</p><p>这难道不疯狂吗？你看不出这有多强大吗？AI远远不止是一个用来抛出无聊问题的地方。我想你可以说，你从AI得到的回复质量，取决于你的视野和能动性的水平。</p><p>在我看来，现在使用AI的重点，是把<em>更多</em>时间花在你喜欢做的事情上（你独特的优势），并构建AI工作流和提示词，让你如果肯花时间“一次搭建，永久使用”，就能以出乎意料的高质量完成其余的事情。</p><p>我个人对营销并不在意，所以我打算像一直以来那样专注于我的写作。</p><p>AI可以帮助提升我的写作，它也可以为落地页、邮件、推广帖子等撰写有说服力的文案。</p><p>这仅仅是AI能让你做到的事情的冰山一角。</p><h3 id="_4-休闲的类型" tabindex="-1">4）休闲的类型 <a class="header-anchor" href="#_4-休闲的类型" aria-label="Permalink to &quot;4）休闲的类型&quot;">​</a></h3><p>我们都明白什么是工作。</p><p>但说到休闲，我常常被问到：</p><p>“如果你工作时间不长，那你一天剩下的时间都在做什么？就坐着无所事事吗？”</p><p>朋友，如果你认为人生中唯一能做的事就是工作，我为你感到非常难过。</p><p>为了便于定义，<strong>休闲是一种心态。</strong></p><p>你可以为了乐趣、休闲或休息而写作，但一旦它和一个为了工作而存在的强制性结果绑定在一起，它就不再是休闲了。</p><p>你可以带着走3000步的外在目标去长途散步，但这个目标往往是一种让大脑从思考走路本身中解放出来的方式。你获得了更多可以分配给解决潜意识问题的心理能量。</p><p>你可以读一本书，但一旦你开始分析并试图<em>从中获取什么</em>，它就变成了工作。</p><p>你可以去健身房、去跑步、做瑜伽、打个盹、做饭、打扫、和朋友社交，你的心智可能会在某种工作和休息之间摆动，但休息的目的应该是不专注于工作。</p><p>对于创造性工作而言，美妙的地方在于，这些活动往往是那项工作的<em>直接燃料</em>。</p><p>由于创造性工作在很大程度上依赖于你所拥有的想法的质量，而你最好的想法大多不是在工作时产生的，休闲就是你开始创造一种工作、休息和玩乐融为一体的生活的方式。</p><p>如果长途散步被视为我工作的一部分——在很多情况下确实如此——那么我就是全天、每天都在工作。甚至我的睡眠也直接为工作做出了贡献。</p><h3 id="_5-负责任的人生自带截止期限" tabindex="-1">5）负责任的人生自带截止期限 <a class="header-anchor" href="#_5-负责任的人生自带截止期限" aria-label="Permalink to &quot;5）负责任的人生自带截止期限&quot;">​</a></h3><p>成功人士常给出的建议是，告诉你在20多岁时要尽可能拼命工作。</p><p>要放弃你生活的大部分。</p><p>但我认为大多数人误解了这句话的意思。</p><p>他们真正想说的是要承担更大的风险。</p><p>赌自己一把，开创自己的道路。</p><p>这不需要16小时的工作，因为你可以在比你的生意更多的事情上努力。</p><p>你有一个心智、一个身体、一种精神，它们也都需要发展。</p><p>你有一些关系，也许不该被忽视，因为那绝对会把一些不受控的念头装进你的脑子里，从而削弱你工作的质量。</p><p>因此，负责任的人生自带截止期限。</p><p>如果你真正重视自己的智力、体格、与他人及现实的联结，以及涵盖这一切的健康标准，你就无法维持16小时的工作。这是不可能的。那些日复一日工作16小时的人，暴露出他们并不重视这些东西，我会质疑你对他们方法的信任。</p><p>如果我重视自己的健康，并明白如果我一天下来很疲惫，我的健身房表现会下降，那么我就需要为我的工作设一个午间截止期限，这样我在健身房的表现才能更接近最佳状态。</p><p>如果我重视和我的伴侣的关系，并明白美好的事物需要<em>持续不断</em>的浇灌，我就不能在充满压力、脑子里只有工作的状态下结束这一天的夜晚。</p><p>这不是对你工作质量的降级，而是升级。</p><p>为什么？</p><p>因为截止期限会让你的注意力变窄，并产生一种紧迫感，这种紧迫感就像深度工作的火箭燃料。</p><p>当你努力追求多维度的强大，并把它当作自己的标准时，你会在早晨感受到那种紧迫感，用你前一天休息时获得的创造力燃料，在那段时间内尽可能完成你能完成的任务。</p><p>再加上帕金森定律——工作会膨胀以填满为完成它所分配的时间——你会惊讶地发现，在这么短的时间里你能完成多少事情。</p><p>当然，结果不会立刻显现。</p><p>适应这种新的生活方式需要几周时间。</p><p>但如果你坚持下去，我保证你的生活会有超出你想象的改善。</p><p>——丹（Dan）</p><hr><p><a href="/en/letters/the-80-hour-myth-why-were-addicted-to-being-busy">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',222))])}const g=l(s,[["render",d]]);export{A as __pageData,g as default};
